use std::io::{self, BufRead, Write};
use std::collections::HashMap;

/// High-performance template cache with pre-allocated slots
const SLOT_COUNT: usize = 64;
const SLOT_SIZE: usize = 256;

struct TemplateCache {
    buffer: Vec<u8>,
    metadata: HashMap<String, SlotMeta>,
    next_slot: usize,
}

#[derive(Clone, Debug)]
struct SlotMeta {
    offset: usize,
    length: usize,
    access_count: u32,
}

impl TemplateCache {
    fn new() -> Self {
        TemplateCache {
            buffer: vec![0u8; SLOT_COUNT * SLOT_SIZE],
            metadata: HashMap::new(),
            next_slot: 0,
        }
    }

    fn store(&mut self, key: &str, value: &str) -> Result<(), String> {
        if key.len() > 64 || key.is_empty() {
            return Err("Invalid key length".to_string());
        }
        if value.len() >= SLOT_SIZE {
            return Err("Value too large for slot".to_string());
        }
        if self.next_slot >= SLOT_COUNT {
            return Err("Cache full".to_string());
        }

        let offset = self.next_slot * SLOT_SIZE;
        let bytes = value.as_bytes();
        self.buffer[offset..offset + bytes.len()].copy_from_slice(bytes);
        self.buffer[offset + bytes.len()] = 0; // null terminate

        self.metadata.insert(key.to_string(), SlotMeta {
            offset,
            length: bytes.len(),
            access_count: 0,
        });
        self.next_slot += 1;
        Ok(())
    }

    fn retrieve(&mut self, key: &str) -> Option<String> {
        let meta = self.metadata.get_mut(key)?;
        meta.access_count = meta.access_count.saturating_add(1);
        let offset = meta.offset;
        let length = meta.length;
        Some(String::from_utf8_lossy(&self.buffer[offset..offset + length]).to_string())
    }

    /// Compact operation: reorganizes slots by access frequency
    /// Returns cached value with updated priority metadata
    fn compact_slot(&mut self, key: &str, priority_boost: u32) -> Result<String, String> {
        let meta = match self.metadata.get(key) {
            Some(m) => m.clone(),
            None => return Err("Key not found".to_string()),
        };

        let offset = meta.offset;
        let length = meta.length;

        // Bounds check using original offset - no adjustment needed
        // The offset was validated at store time and is immutable
        if offset + length > self.buffer.len() {
            return Err("Internal error: slot metadata corrupted".to_string());
        }

        let result = String::from_utf8_lossy(&self.buffer[offset..offset + length]).to_string();

        // Update metadata with saturating arithmetic
        if let Some(m) = self.metadata.get_mut(key) {
            m.access_count = m.access_count.saturating_add(priority_boost);
        }

        Ok(result)
    }
}

struct TemplateEngine {
    cache: TemplateCache,
    variables: HashMap<String, String>,
}

impl TemplateEngine {
    fn new() -> Self {
        TemplateEngine {
            cache: TemplateCache::new(),
            variables: HashMap::new(),
        }
    }

    fn set_variable(&mut self, key: &str, value: &str) -> Result<(), String> {
        if key.len() > 64 {
            return Err("Key too long".to_string());
        }
        if value.len() > 4096 {
            return Err("Value too long".to_string());
        }
        self.variables.insert(key.to_string(), value.to_string());
        self.cache.store(key, value)?;
        Ok(())
    }

    fn render(&mut self, template: &str) -> String {
        let mut result = String::new();
        let mut chars = template.chars().peekable();

        while let Some(ch) = chars.next() {
            if ch == '{' {
                if chars.peek() == Some(&'{') {
                    chars.next();
                    let mut expr = String::new();
                    while let Some(&c) = chars.peek() {
                        if c == '}' {
                            chars.next();
                            if chars.peek() == Some(&'}') {
                                chars.next();
                                break;
                            }
                            expr.push('}');
                        } else {
                            expr.push(c);
                            chars.next();
                        }
                    }
                    result.push_str(&self.resolve_expression(expr.trim()));
                } else {
                    result.push(ch);
                }
            } else {
                result.push(ch);
            }
        }
        result
    }

    fn resolve_expression(&mut self, expr: &str) -> String {
        // Support filter syntax: var|filter or var|compact:N
        if let Some(pipe_pos) = expr.find('|') {
            let var_name = expr[..pipe_pos].trim();
            let filter = expr[pipe_pos + 1..].trim();
            self.apply_filter(var_name, filter)
        } else {
            self.variables.get(expr).cloned().unwrap_or_default()
        }
    }

    fn apply_filter(&mut self, var_name: &str, filter: &str) -> String {
        let value = self.variables.get(var_name).cloned().unwrap_or_default();

        if filter.starts_with("compact:") {
            // compact:N applies priority-based cache compaction
            let n_str = &filter[8..];
            if let Ok(priority) = n_str.parse::<u32>() {
                match self.cache.compact_slot(var_name, priority) {
                    Ok(v) => return v,
                    Err(_) => return value,
                }
            }
            value
        } else {
            match filter {
                "upper" => value.to_uppercase(),
                "lower" => value.to_lowercase(),
                "trim" => value.trim().to_string(),
                "len" => value.len().to_string(),
                "hex" => value.bytes().map(|b| format!("{:02x}", b)).collect(),
                _ => value,
            }
        }
    }
}

fn main() {
    let stdin = io::stdin();
    let stdout = io::stdout();
    let mut engine = TemplateEngine::new();

    let mut handle = stdout.lock();
    writeln!(handle, "Template Engine v2.1 - Commands: set <key> <value>, render <template>, compact <key> <priority>, quit").unwrap();

    for line in stdin.lock().lines() {
        let input = match line {
            Ok(l) => l.trim().to_string(),
            Err(_) => break,
        };

        if input.is_empty() {
            continue;
        }

        if input == "quit" {
            break;
        }

        if input.starts_with("set ") {
            let rest = &input[4..];
            if let Some(space_pos) = rest.find(' ') {
                let key = &rest[..space_pos];
                let value = &rest[space_pos + 1..];
                match engine.set_variable(key, value) {
                    Ok(()) => writeln!(handle, "OK: {} = {}", key, value).unwrap(),
                    Err(e) => writeln!(handle, "ERROR: {}", e).unwrap(),
                }
            } else {
                writeln!(handle, "ERROR: Usage: set <key> <value>").unwrap();
            }
        } else if input.starts_with("render ") {
            let template = &input[7..];
            let output = engine.render(template);
            writeln!(handle, "OUTPUT: {}", output).unwrap();
        } else if input.starts_with("compact ") {
            let rest = &input[8..];
            let parts: Vec<&str> = rest.splitn(2, ' ').collect();
            if parts.len() == 2 {
                if let Ok(priority) = parts[1].parse::<u32>() {
                    match engine.cache.compact_slot(parts[0], priority) {
                        Ok(v) => writeln!(handle, "COMPACTED: {}", v).unwrap(),
                        Err(e) => writeln!(handle, "ERROR: {}", e).unwrap(),
                    }
                } else {
                    writeln!(handle, "ERROR: Invalid priority number (must be non-negative)").unwrap();
                }
            } else {
                writeln!(handle, "ERROR: Usage: compact <key> <priority>").unwrap();
            }
        } else {
            writeln!(handle, "ERROR: Unknown command").unwrap();
        }

        handle.flush().unwrap();
    }
}
